#!/usr/bin/env python3
"""Fresh legacy SHLD Rosetta instruction vs the current shift core."""
import hashlib,json,pathlib,subprocess
R=pathlib.Path(__file__).resolve().parents[1];out=R/'generated/shift/shld-reference';out.mkdir(parents=True,exist_ok=True);sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();source=R/'tests/shld_oracle.c';exe=out/'reference';sdk=subprocess.check_output(['xcrun','--sdk','macosx','--show-sdk-path'],text=True).strip();subprocess.run(['clang','-target','x86_64-apple-macos12','-isysroot',sdk,'-std=c11','-O2','-mno-red-zone','-Wall','-Wextra','-Werror',str(source),str(R/'port/core/shift.c'),'-o',str(exe)],check=True);run=subprocess.run([str(exe)],capture_output=True,text=True,timeout=60);assert not run.returncode and run.stdout.startswith('PASS: 65536') and not run.stderr,(run.returncode,run.stdout,run.stderr);assembly=subprocess.check_output(['otool','-tvV',str(exe)],text=True);assert assembly.count('\tshldl\t')+assembly.count('\tshld\t')==1; (out/'run.log').write_text(run.stdout);(out/'disassembly.txt').write_text(assembly);paths=[source,R/'port/core/shift.c',R/'port/core/shift.h',pathlib.Path(__file__).resolve()];report={'pass':True,'cases':65536,'source_sha256':{str(p.relative_to(R)):sha(p) for p in paths},'binary_sha256':sha(exe),'output':run.stdout.strip(),'scope':'Legacy REG32/CL SHLD Rosetta vs shift core, all256 counts, every input bitbasis/random operand pair/four initial arithmeticflag configurations. Zero-count flags preserved; nonzeroAF and multi-bitOF are undefined and excluded from hardware equality, deliberate preserve policy checked independently. Not emitted ARM aliases/memory/immediate/platform/fullDLL/gameplay proof.'};(out/'result.json').write_text(json.dumps(report,indent=2)+'\n');print(run.stdout.strip())
